    /// Rule 3, per field: every rate above zero, and cache read no more than input.
    static func fieldsValid(_ r: TokenRates) -> Bool {
        r.input > 0 && r.output > 0 && r.cacheRead > 0 && r.cacheRead <= r.input && (r.cacheWrite.map { $0 > 0 } ?? true)
    }

