import Foundation

/// Single source of truth for every path under the home config directory (`~/.iris`).
///
/// Storage is segregated by owner: `memory/` (bot-authored, mutable, guard-sanitized),
/// `config/` (human/app config), and `models/` (downloaded bundles). Every consumer resolves
/// paths through here instead of re-deriving `("~/.iris" as NSString).expandingTildeInPath`,
/// which removes the duplication that produced the SOUL split-brain bug. `root` is injectable
/// so `IrisMigrator` and the memory managers can be unit-tested against a temp directory.
///
/// NOTE: `expandingTildeInPath` silently truncates its result to PATH_MAX, so it cannot be used
/// to measure a path's length — `IrisEngine.expandTilde` expands without that, and
/// `IrisEngine.workspaceRefusal` is where the resulting length rule lives (#273).
struct IrisPaths: Sendable {
    let root: URL

    init(root: URL) { self.root = root }

    /// The home every consumer resolves through. A headless perf run installs a volatile copy
    /// (see `useVolatileCopy(at:)`) before any manager is touched; nothing else ever sets it.
    static var `default`: IrisPaths { lock.withLock { override } ?? processDefault }

    /// `standard`, except under `swift test`, where it is an empty home per test process (#304).
    /// Without it every `.shared` manager in the suite read and wrote the developer's real
    /// `~/.iris`, and invariant 7 held for it only by habit: one `allowGlobally` in a test wrote a
    /// real allow rule on every run (#290). Empty rather than a copy, so no assertion can depend
    /// on what the developer happens to have there. Same XCTest signal as `IrisDefaults`.
    /// Removed at exit, or — if a detached task was still writing, or the run was killed — by the
    /// next run's sweep.
    private static let processDefault: IrisPaths = {
        guard NSClassFromString("XCTestCase") != nil else { return standard }
        for stale in staleTestHomes(in: testHomesDir, isAlive: IrisDefaults.isProcessAlive) {
            try? FileManager.default.removeItem(at: stale)
        }
        let home = IrisPaths(root: testHomesDir.appendingPathComponent(
            String(ProcessInfo.processInfo.processIdentifier), isDirectory: true))
        try? FileManager.default.removeItem(at: home.root)   // a recycled pid's leftovers
        try? home.ensureDirectories()
        atexit { try? FileManager.default.removeItem(at: IrisPaths.processDefault.root) }
        return home
    }()

    /// One directory of our own for the test homes, each named by its pid. The sweep must never
    /// list `$TMPDIR` itself: `processDefault` is a `static let`, so every thread touching
    /// `default` parks until it returns, and a crowded temp directory (212k entries on one
    /// machine, ~8s in `contentsOfDirectory(atPath:)`) stalled the whole parallel run past
    /// unrelated suites' wall-clock bounds. This one holds an entry per test process at most.
    static let testHomesDir = FileManager.default.temporaryDirectory
        .appendingPathComponent("iris-tests-homes", isDirectory: true)

    /// Test homes under `directory` whose process is gone — a run that crashed or was killed
    /// before its atexit. This process and live runs are skipped.
    static func staleTestHomes(in directory: URL, isAlive: (pid_t) -> Bool) -> [URL] {
        let me = ProcessInfo.processInfo.processIdentifier
        let names = (try? FileManager.default.contentsOfDirectory(atPath: directory.path)) ?? []
        return names.sorted().compactMap { name in
            guard let pid = pid_t(name), pid != me, !isAlive(pid) else { return nil }
            return directory.appendingPathComponent(name, isDirectory: true)
        }
    }

    /// The current identity's real home (`~/.iris` for the installed app, `~/.iris-dev` for every
    /// dev build and test process), regardless of any headless override. Isolation tests compare
    /// file existence here and at `release` before and after a run and must never create anything
    /// in either.
    static let standard = home(for: .current)

    /// The installed app's home, whatever this process is. `--seed-dev-home` reads it as the
    /// seed source; isolation tests also read it, to assert that nothing under test ever
    /// touches it.
    static let release = home(for: .release)

    static func home(for identity: BuildIdentity,
                     homeDirectory: URL = FileManager.default.homeDirectoryForCurrentUser) -> IrisPaths {
        IrisPaths(root: homeDirectory.appendingPathComponent(identity.homeDirectoryName, isDirectory: true))
    }

    private static let lock = NSLock()
    nonisolated(unsafe) private static var override: IrisPaths?

    /// True only inside a headless run that installed a copy. Under `swift test` this is false
    /// even though `default` is not the real home: that is `processDefault`, not an override.
    static var isVolatileCopy: Bool { lock.withLock { override != nil } }

    /// Route every path at a fresh copy of the real home under `root` for the rest of the
    /// process. Real-lane perf runs wrote to the user's USER.md and fact store through
    /// `IrisPaths.default`, which neither the sandbox (run_command only) nor the scratch cwd
    /// (relative file tools only) covers. Must run before `MemoryManager.shared`,
    /// `FactStoreManager.shared`, or any other consumer captures `.default`.
    static func useVolatileCopy(at root: URL) throws {
        let copy = try makeVolatileCopy(of: standard, at: root)
        lock.withLock { override = copy }
    }

    /// Copy memory/, rules/, config/ and plugins/ into `root`; models/ is a symlink to the
    /// source (gigabytes, read-only). Reads see the same context; writes stay in the copy.
    static func makeVolatileCopy(of source: IrisPaths, at root: URL) throws -> IrisPaths {
        let fm = FileManager.default
        try fm.createDirectory(at: root, withIntermediateDirectories: true)
        for dir in [source.memoryDir, source.rulesDir, source.configDir, source.pluginsDir] {
            let dest = root.appendingPathComponent(dir.lastPathComponent)
            if fm.fileExists(atPath: dir.path) {
                try fm.copyItem(at: dir, to: dest)
            } else {
                try fm.createDirectory(at: dest, withIntermediateDirectories: true)
            }
        }
        let modelsLink = root.appendingPathComponent(source.modelsDir.lastPathComponent)
        if fm.fileExists(atPath: source.modelsDir.path) {
            try fm.createSymbolicLink(at: modelsLink, withDestinationURL: source.modelsDir)
        } else {
            try fm.createDirectory(at: modelsLink, withIntermediateDirectories: true)
        }
        return IrisPaths(root: root)
    }

    /// A digest of every file's relative path, size and modification time under `dir`.
    /// A perf run compares the real memory directory's fingerprint before and after so a leak
    /// through some path the copy does not cover fails loudly instead of silently.
    static func fingerprint(of dir: URL) -> String {
        let fm = FileManager.default
        var lines: [String] = []
        if let e = fm.enumerator(at: dir, includingPropertiesForKeys: [.fileSizeKey, .contentModificationDateKey], options: [.skipsHiddenFiles]) {
            for case let url as URL in e {
                let v = try? url.resourceValues(forKeys: [.fileSizeKey, .contentModificationDateKey, .isDirectoryKey])
                if v?.isDirectory == true { continue }
                let rel = url.path.dropFirst(dir.path.count)
                lines.append("\(rel)|\(v?.fileSize ?? -1)|\(v?.contentModificationDate?.timeIntervalSince1970 ?? 0)")
            }
        }
        return lines.sorted().joined(separator: "\n")
    }

    /// The conversation store (#163). At the root on purpose: `makeVolatileCopy` copies only
    /// memory/, rules/, config/ and plugins/, so a headless copy starts with no conversations,
    /// which is the choice `IrisDefaults.stripConversationBlob` already made for the old blob.
    var conversationsDB: URL { root.appendingPathComponent("conversations.sqlite") }

    /// Written by `iris --seed-dev-home` into the home it creates. Its absence in a dev home that
    /// exists beside a release one means something else created that home first (a `swift run`
    /// before `run-dev.sh`), so it was never seeded; `run-dev.sh` and perf say so.
    var seedMarker: URL { root.appendingPathComponent(".seeded-from-release") }

    /// The lock that makes one process at a time the store's only writer (#463). Whoever holds
    /// its `flock` may open `conversations.sqlite`; nobody else may. Held for the holder's whole
    /// life and never unlinked, so the kernel releases it on any exit, SIGKILL included. Beside
    /// the database on purpose: it guards *that file*, and a volatile copy gets its own lock.
    var storeLockFile: URL { conversationsDB.appendingPathExtension("lock") }

    // memory/
    var memoryDir: URL { root.appendingPathComponent("memory") }
    var soulMd: URL { memoryDir.appendingPathComponent("SOUL.md") }
    var userMd: URL { memoryDir.appendingPathComponent("USER.md") }
    var memoryMd: URL { memoryDir.appendingPathComponent("memory.md") }
    var skillsDir: URL { memoryDir.appendingPathComponent("skills") }
    var artifactsDir: URL { memoryDir.appendingPathComponent("artifacts") }
    var libraryDir: URL { memoryDir.appendingPathComponent("library") }
    var factStoreDB: URL { memoryDir.appendingPathComponent("fact_store.sqlite") }
    var holographicDB: URL { memoryDir.appendingPathComponent("holographic_memory.sqlite") }

    // config/
    var configDir: URL { root.appendingPathComponent("config") }
    var settingsJSON: URL { configDir.appendingPathComponent("settings.json") }
    var permissionsJSON: URL { configDir.appendingPathComponent("permissions.json") }
    var mcpServersJSON: URL { configDir.appendingPathComponent("mcp_servers.json") }

    // metrics/: measurements kept for this Mac's own use, never sent (#238)
    var metricsDir: URL { root.appendingPathComponent("metrics") }
    var tier2ScoresJSON: URL { metricsDir.appendingPathComponent("tier2-scores.json") }

    // rules/
    var rulesDir: URL { root.appendingPathComponent("rules") }

    // plugins/
    var pluginsDir: URL { root.appendingPathComponent("plugins") }
    var pluginsJSON: URL { configDir.appendingPathComponent("plugins.json") }

    // models/ (resolved path unchanged from the old layout)
    var modelsDir: URL { root.appendingPathComponent("models") }

    /// Goal workspaces created by `GoalWorkspace.resolve` (#68). Every directory directly under
    /// here was created by Iris; this is the eligibility boundary the workspace inventory (#126)
    /// uses to decide what it may ever list or delete.
    var workspacesDir: URL { root.appendingPathComponent("workspaces") }

    /// The directories a write into is a grant, not a file edit. `PermissionManager` never
    /// auto-allows one (#187):
    ///
    /// - `config/` holds permissions.json itself, the hook definitions and the plugin config, and
    ///   the allowlist is re-read on every call — one carved-out write there grants all the rest.
    /// - `plugins/` is the same thing one step removed: a plugin with an `mcp` component spawns a
    ///   command at the next launch, and `PluginState` defaults to enabled.
    ///
    /// `rules/` is deliberately NOT here: it is prompt persistence, which the guard already treats
    /// as untrusted content, not a way to make something execute.
    /// Session artifacts (#469 §7): content-addressed, written only by the harness.
    var exchangeDir: URL { root.appendingPathComponent("exchange") }

    var protectedWriteDirs: [URL] { [configDir, pluginsDir, exchangeDir] }

    /// True if `rawPath` resolves inside the exchange (#469 §7.6 B): read only through
    /// `iris-artifact://`, which checks the reader's reference and the content's hash.
    func isUnderExchangeDir(_ rawPath: String) -> Bool {
        let base = Self.realPath(exchangeDir.path).lowercased()
        let target = Self.realPath(rawPath).lowercased()
        return target == base || target.hasPrefix(base + "/")
    }

    /// True if `rawPath` resolves to a location inside one of `protectedWriteDirs`.
    ///
    /// Canonical, not merely standardized: APFS is case-insensitive by default, so `~/.iris/CONFIG`
    /// is the same directory as `~/.iris/config`, and a symlink planted in a writable directory
    /// (`memory/cfg -> config`) is a legal path to a protected target. Both sides go through
    /// `realPath` and are compared case-insensitively. This is a DENY check only — never
    /// reuse it to widen an allow, where resolving a symlink the other way would let a link
    /// smuggle an outside path into the carve-out. Real paths, not `canonicalPath`: that one
    /// collapses `..` before following a symlink, and `link/../config` with `link → ~/.iris` is
    /// inside `config` on disk and outside it lexically (#282 §0.9).
    func isUnderProtectedWriteDir(_ rawPath: String) -> Bool {
        let candidate = Self.realPath(rawPath).lowercased()
        return protectedWriteDirs.contains { dir in
            let base = Self.realPath(dir.path).lowercased()
            return candidate == base || candidate.hasPrefix(base + "/")
        }
    }

    /// Tilde-expanded, `..`-resolved, and with symlinks resolved on the deepest ancestor that
    /// actually exists — the file being written usually does not yet, and `resolvingSymlinksInPath`
    /// leaves a path alone when it cannot stat it.
    static func canonicalPath(_ rawPath: String) -> String {
        let expanded = IrisEngine.expandTilde(rawPath)   // #275: never `expandingTildeInPath` on a decider
        var url = URL(fileURLWithPath: expanded).standardizedFileURL
        let fm = FileManager.default
        var missing: [String] = []
        while !fm.fileExists(atPath: url.path), url.pathComponents.count > 1 {
            missing.append(url.lastPathComponent)
            url = url.deletingLastPathComponent()
        }
        var resolved = url.resolvingSymlinksInPath()
        for component in missing.reversed() { resolved.appendPathComponent(component) }
        return resolved.standardizedFileURL.path
    }

    /// The path the kernel would act on (#282 §0.9): tilde expanded, then `realpath(3)` of the
    /// deepest existing ancestor of the *unstandardised* components — so a symlink is followed
    /// before a `..` that follows it, which is the one thing `canonicalPath` gets wrong — with
    /// the remaining components appended. A `..` among the missing tail pops lexically: a
    /// directory that does not exist cannot be a symlink. `canonicalPath` stays for the callers
    /// that store and display paths; this is for deciding.
    ///
    /// One exception to "what the kernel would act on": a DANGLING final symlink (or a loop) is
    /// returned as its spelling under the resolved parent, while `open(O_CREAT)` would create the
    /// link's *target*. Three things hold that shut: `realPathForAllow` refuses it (an entry that
    /// `lstat` sees but `realpath(3)` cannot resolve is nil on the allow side), `ToolExecutor.writeFile`
    /// writes atomically, so its rename replaces the link rather than following it, and Task 4c's
    /// walk opens the final component `O_NOFOLLOW`. This lenient form is for the deny side.
    static func realPath(_ rawPath: String) -> String {
        realPath(rawPath, strict: false) ?? "/"   // strict: false never returns nil; `/` is the last resort
    }

    /// `realPath` for an *allow*: nil when the path is not absolute after tilde expansion, any
    /// component is `..` (§0.9) — a model never needs either inside a grant, and refusing them
    /// costs nothing a person could not have phrased without them — or the deepest existing
    /// entry will not resolve (a loop, a dangling link, EACCES, a component swapped between the
    /// existence check and `realpath(3)`): an allow must not step past what it could not see.
    static func realPathForAllow(_ rawPath: String) -> String? {
        let expanded = IrisEngine.expandTilde(rawPath)   // #275: never `expandingTildeInPath` on a decider
        guard expanded.hasPrefix("/") else { return nil }
        guard !expanded.split(separator: "/").contains("..") else { return nil }
        return realPath(expanded, strict: true)
    }

    /// The walk both forms share. Existence is `lstat`'s, not `stat`'s, so a symlink that does not
    /// resolve is met as the deepest existing entry and `realpath(3)` is asked about *it*: strict
    /// answers nil there; lenient steps back one more and appends the rest lexically, which is
    /// the answer the deny side has always had. Only `/` itself is trusted without asking.
    private static func realPath(_ rawPath: String, strict: Bool) -> String? {
        let expanded = IrisEngine.expandTilde(rawPath)   // #275: never `expandingTildeInPath` on a decider
        let absolute = expanded.hasPrefix("/") ? expanded : URL(fileURLWithPath: expanded).path
        let components = absolute.split(separator: "/", omittingEmptySubsequences: true).map(String.init)
            .filter { $0 != "." }
        var existing = components.count
        var resolved = "/"
        while existing > 0 {
            let prefix = "/" + components[0..<existing].joined(separator: "/")
            var info = stat()
            if lstat(prefix, &info) == 0 {
                if let real = Darwin.realpath(prefix, nil) {
                    resolved = String(cString: real)
                    free(real)
                    break
                }
                if strict { return nil }
            }
            existing -= 1
        }
        for component in components[existing...] {
            if component == ".." {
                resolved = (resolved as NSString).deletingLastPathComponent
            } else {
                resolved = (resolved as NSString).appendingPathComponent(component)
            }
        }
        return resolved
    }

    /// `/tmp`, `/var` and `/etc` spelled as the `/private` directories they link to. Those three
    /// links are the system's, not something a run can swap, so following them here is not a
    /// fresh resolution; a path recorded through one (an older card, a temp directory) can then be
    /// walked with no link followed (#256). Any other spelling is returned unchanged.
    static func throughPrivate(_ path: String) -> String {
        for link in ["/tmp", "/var", "/etc"] where path == link || path.hasPrefix(link + "/") {
            return "/private" + path
        }
        return path
    }

    /// Whether two real paths (`realPath` output) name the same file. Exact, or equal but for case
    /// on a case-insensitive volume (#256). `realPath` already returns the on-disk case of every
    /// existing component, so the two can differ in case only in a tail that does not exist yet,
    /// which lives on the volume of the deepest existing ancestor — the one asked here.
    static func samePath(_ a: String, _ b: String) -> Bool {
        if a == b { return true }
        guard a.lowercased() == b.lowercased() else { return false }
        var url = URL(fileURLWithPath: a)
        while !FileManager.default.fileExists(atPath: url.path), url.pathComponents.count > 1 {
            url = url.deletingLastPathComponent()
        }
        guard let sensitive = try? url.resourceValues(forKeys: [.volumeSupportsCaseSensitiveNamesKey])
                .volumeSupportsCaseSensitiveNames else { return false }
        return !sensitive
    }

    /// True if `rawPath` resolves to a location inside `root` (`~/.iris`).
    /// Tilde-expands (via `IrisEngine.expandTilde`) and standardizes the path (resolving `..`)
    /// first. A literal `~/.iris` spelling always expands through `IrisPaths.default`, so on an
    /// instance whose `root` differs from `.default` the `~` form is checked against the
    /// process's default home, not against this instance's own `root` — only an already-expanded
    /// (or otherwise-spelled) path is checked against `root`.
    func isUnderIrisDir(_ rawPath: String) -> Bool {
        let expanded = IrisEngine.expandTilde(rawPath)   // #275: never `expandingTildeInPath` on a decider
        let resolved = URL(fileURLWithPath: expanded).standardizedFileURL.path
        // The root's real path too: a file tool's path arrives already resolved (#256), so a home
        // reached through a link (`/var` → `/private/var`) is spelled by its target.
        return Set([root.standardizedFileURL.path, Self.realPath(root.path)]).contains { rootPath in
            resolved == rootPath || resolved.hasPrefix(rootPath + "/")
        }
    }

    /// `root` as the model should write it: `~/...` when under the user's home.
    var displayRoot: String {
        let home = NSHomeDirectory()
        let path = root.standardizedFileURL.path
        return path.hasPrefix(home + "/") ? "~" + path.dropFirst(home.count) : path
    }

    /// Bundled text spells the home `~/.iris`. Rewrites it to `displayRoot` so a dev agent is
    /// pointed at `~/.iris-dev`, in prompts and in shell commands it copies from them.
    ///
    /// The lookahead excludes a longer name (`-dev`, `rc`, …) and a suffix that starts with a
    /// `.` only when a letter or digit follows that `.` (`.bak`): a sentence-final period is
    /// not excluded, so "stored in ~/.iris." still rewrites to "stored in ~/.iris-dev.".
    func agentFacing(_ text: String) -> String {
        text.replacing(/~\/\.iris(?![A-Za-z0-9_\-]|\.[A-Za-z0-9])/, with: { _ in displayRoot })
    }

    /// Create the bucket directories if absent. Called by the migrator and by managers that
    /// need their directory to exist before writing.
    func ensureDirectories() throws {
        for dir in [memoryDir, skillsDir, artifactsDir, libraryDir, configDir, modelsDir, rulesDir, pluginsDir] {
            try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        }
    }
}

import Testing
import Foundation
@testable import IrisKit

/// #282 §0.13 — the descriptor walk. Temp directories only; every "outside" is a sibling temp dir
/// the test checks stayed empty.
@Suite("Granted writes go through a descriptor walk (#282)", .timeLimit(.minutes(1)))
struct GrantedWriteTests {
    struct Tree {
        let base: URL; let root: URL; let outside: URL
        func tearDown() { try? FileManager.default.removeItem(at: base) }
        var access: GrantedFileAccess { GrantedFileAccess(root: root.path) }
        func names(_ dir: URL) -> [String] { (try? FileManager.default.contentsOfDirectory(atPath: dir.path))?.sorted() ?? [] }
    }

    private func tree() throws -> Tree {
        let fm = FileManager.default
        let base = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent("iris-gwalk-\(UUID().uuidString)")
        let root = base.appendingPathComponent("mount"), outside = base.appendingPathComponent("outside")
        try fm.createDirectory(at: root.appendingPathComponent("sub"), withIntermediateDirectories: true)
        try fm.createDirectory(at: outside, withIntermediateDirectories: true)
        return Tree(base: base, root: root, outside: outside)
    }

    @Test("a write through the walk lands, atomically, with no staging file left behind; a second write replaces")
    func writeLands() throws {
        let t = try tree(); defer { t.tearDown() }
        try t.access.write(relative: ["sub", "x.md"], content: "one")
        #expect(try String(contentsOf: t.root.appendingPathComponent("sub/x.md"), encoding: .utf8) == "one")
        #expect(t.names(t.root.appendingPathComponent("sub")) == ["x.md"], "the staging file was renamed away, not left")
        try t.access.write(relative: ["sub", "x.md"], content: "two")
        #expect(try String(contentsOf: t.root.appendingPathComponent("sub/x.md"), encoding: .utf8) == "two")
        try t.access.write(relative: ["top.md"], content: "")
        #expect(try String(contentsOf: t.root.appendingPathComponent("top.md"), encoding: .utf8) == "")
    }

    @Test("a rewrite keeps the existing file's mode bits, as Foundation's atomic write does; a new file gets the default")
    func rewriteKeepsMode() throws {
        let t = try tree(); defer { t.tearDown() }
        func mode(_ url: URL) -> mode_t {
            var st = stat()
            #expect(lstat(url.path, &st) == 0)
            return st.st_mode & 0o7777
        }
        // Measured: `write(atomically:)` — the attended path — leaves a 755 script at 755. A job that
        // maintains `deploy.sh` and then runs it must not find it 644 in the container.
        let script = t.root.appendingPathComponent("sub/deploy.sh")
        try "#!/bin/sh\necho one\n".write(to: script, atomically: true, encoding: .utf8)
        #expect(chmod(script.path, 0o755) == 0)
        try t.access.write(relative: ["sub", "deploy.sh"], content: "#!/bin/sh\necho two\n")
        #expect(mode(script) == 0o755, "the rewrite keeps +x and every other bit")
        #expect(try String(contentsOf: script, encoding: .utf8) == "#!/bin/sh\necho two\n")
        #expect(t.names(t.root.appendingPathComponent("sub")) == ["deploy.sh"])
        // A file that did not exist gets the default: owner-readable, never executable.
        try t.access.write(relative: ["sub", "fresh.md"], content: "x")
        let fresh = mode(t.root.appendingPathComponent("sub/fresh.md"))
        #expect(fresh & 0o111 == 0 && fresh & 0o600 == 0o600, "fresh file mode \(String(fresh, radix: 8))")
    }

    @Test("a symlink as an intermediate component is refused, and nothing lands outside")
    func intermediateSymlinkRefused() throws {
        let t = try tree(); defer { t.tearDown() }
        try FileManager.default.createSymbolicLink(at: t.root.appendingPathComponent("link"), withDestinationURL: t.outside)
        #expect(throws: GrantedFileError.symlink(component: "link")) {
            try t.access.write(relative: ["link", "x.md"], content: "leak")
        }
        #expect(t.names(t.outside).isEmpty)
        #expect(throws: GrantedFileError.symlink(component: "link")) { _ = try t.access.read(relative: ["link", "x.md"]) }
    }

    @Test("a symlink as the final component is refused rather than followed or replaced")
    func finalSymlinkRefused() throws {
        let t = try tree(); defer { t.tearDown() }
        let target = t.outside.appendingPathComponent("target.md")
        try "keep".write(to: target, atomically: true, encoding: .utf8)
        try FileManager.default.createSymbolicLink(at: t.root.appendingPathComponent("out.md"), withDestinationURL: target)
        #expect(throws: GrantedFileError.symlink(component: "out.md")) {
            try t.access.write(relative: ["out.md"], content: "leak")
        }
        #expect(try String(contentsOf: target, encoding: .utf8) == "keep")
        #expect(t.names(t.root) == ["out.md", "sub"], "the link itself is left where it was")
        #expect(throws: GrantedFileError.symlink(component: "out.md")) { _ = try t.access.read(relative: ["out.md"]) }
        // A directory where a file was named is refused with its own sentence (L2) before anything is staged.
        #expect(throws: GrantedFileError.isADirectory(component: "sub")) { try t.access.write(relative: ["sub"], content: "x") }
        #expect(t.names(t.root) == ["out.md", "sub"])
    }

    @Test("a component swapped for a symlink after the allow and before the write is refused (the §0.13 race)")
    func swapAfterAllowRefused() throws {
        let t = try tree(); defer { t.tearDown() }
        // The allow, as the dispatcher makes it: the path is judged, `sub` is a real directory.
        let sub = t.root.appendingPathComponent("sub")
        var isDir: ObjCBool = false
        #expect(FileManager.default.fileExists(atPath: sub.path, isDirectory: &isDir) && isDir.boolValue)
        // The swap, as a background `cmd &` in the container would make it on the identity-mapped mount.
        try FileManager.default.removeItem(at: sub)
        try FileManager.default.createSymbolicLink(at: sub, withDestinationURL: t.outside)
        // The write, with the components decided before the swap.
        #expect(throws: GrantedFileError.symlink(component: "sub")) {
            try t.access.write(relative: ["sub", "x.md"], content: "leak")
        }
        #expect(t.names(t.outside).isEmpty)
    }

    @Test("the staging file is created inside the final directory's descriptor, exclusively, and matches the watches' sibling rule")
    func stagingStaysInside() throws {
        let t = try tree(); defer { t.tearDown() }
        let staging = GrantedFileAccess.defaultStagingName("x.md")
        #expect(staging.hasPrefix("x.md.sb-"))
        #expect(RecentWrites.isAtomicTempSibling(staging, of: "x.md"), "a watch absorbs the staging file as the run's own write")
        // A fixed staging name that already exists: O_EXCL refuses, and the existing file is untouched.
        let fixed = GrantedFileAccess(root: t.root.path, stagingName: { _ in "x.md.sb-fixed" })
        try "occupied".write(to: t.root.appendingPathComponent("sub/x.md.sb-fixed"), atomically: true, encoding: .utf8)
        #expect(throws: GrantedFileError.stagingExists("x.md.sb-fixed")) {
            try fixed.write(relative: ["sub", "x.md"], content: "new")
        }
        #expect(try String(contentsOf: t.root.appendingPathComponent("sub/x.md.sb-fixed"), encoding: .utf8) == "occupied")
        #expect(!FileManager.default.fileExists(atPath: t.root.appendingPathComponent("sub/x.md").path))
        // A root that is itself a symlink is refused by step 2 of the root open (its real path does
        // not canonicalise back to the stored spelling), naming the swapped component.
        let linkRoot = t.base.appendingPathComponent("rootlink")
        try FileManager.default.createSymbolicLink(at: linkRoot, withDestinationURL: t.root)
        #expect(throws: GrantedFileError.symlink(component: "rootlink")) {
            try GrantedFileAccess(root: linkRoot.path).write(relative: ["y.md"], content: "x")
        }
    }

    @Test("the walk refuses .., ., empty and slash-bearing components itself, before any syscall (H2)")
    func dotDotRefusedByTheWalk() throws {
        let t = try tree(); defer { t.tearDown() }
        // Measured without the guard: `..` is a real directory entry, `openat(O_DIRECTORY|O_NOFOLLOW)` opens it,
        // and esc.md lands outside the root. The guard is the walk's own; it does not rely on the allow having run.
        #expect(throws: GrantedFileError.badComponent("..")) { try t.access.write(relative: ["..", "outside", "esc.md"], content: "leak") }
        #expect(throws: GrantedFileError.badComponent("..")) { try t.access.write(relative: ["sub", "..", "x.md"], content: "leak") }
        #expect(throws: GrantedFileError.badComponent("..")) { _ = try t.access.read(relative: ["..", "outside", "esc.md"]) }
        #expect(throws: GrantedFileError.badComponent(".")) { try t.access.write(relative: [".", "x.md"], content: "x") }
        #expect(throws: GrantedFileError.badComponent("")) { try t.access.write(relative: ["", "x.md"], content: "x") }
        #expect(throws: GrantedFileError.badComponent("a/b")) { try t.access.write(relative: ["a/b"], content: "x") }
        #expect(t.names(t.outside).isEmpty)
        #expect(t.names(t.root) == ["sub"], "nothing was created at all")
    }

    @Test("a nested mount root is reached by the same walk: an intermediate of the root swapped for a link is refused (M2)")
    func nestedRootIntermediateSwapRefused() throws {
        let t = try tree(); defer { t.tearDown() }
        // The grant's inner entry is `mount/inner/leaf`; `mount/` is read-write, so a command can rename `inner`.
        let leaf = t.root.appendingPathComponent("inner/leaf")
        try FileManager.default.createDirectory(at: leaf, withIntermediateDirectories: true)
        try FileManager.default.createDirectory(at: t.outside.appendingPathComponent("leaf"), withIntermediateDirectories: true)
        let access = GrantedFileAccess(root: leaf.path)
        try access.write(relative: ["ok.md"], content: "in")            // before the swap: lands
        try FileManager.default.removeItem(at: t.root.appendingPathComponent("inner"))
        try FileManager.default.createSymbolicLink(at: t.root.appendingPathComponent("inner"), withDestinationURL: t.outside)
        // Measured: `open(root, O_DIRECTORY|O_NOFOLLOW)` followed `inner` and z.md landed in outside/leaf.
        // Now: realpath(root) = …/outside/leaf, whose canonical form is not the stored root → refused at `inner`.
        #expect(throws: GrantedFileError.symlink(component: "inner")) { try access.write(relative: ["z.md"], content: "leak") }
        #expect(throws: GrantedFileError.symlink(component: "inner")) { _ = try access.read(relative: ["ok.md"]) }
        #expect(t.names(t.outside.appendingPathComponent("leaf")).isEmpty)
    }

    @Test("a root whose case was changed since the grant is refused as renamed, not as a symlink crossing")
    func caseRenamedRootIsRefusedAsRenamed() throws {
        let t = try tree(); defer { t.tearDown() }
        // On a case-insensitive volume `mount` still resolves after the rename, but realpath returns
        // the new on-disk case, so step 2 of the root open mismatches; the sentence should say what
        // happened rather than accuse an innocent component of being a symlink. On a case-sensitive
        // volume the rename makes a different directory and the root is simply gone.
        let caseSensitive = try t.base.resourceValues(forKeys: [.volumeSupportsCaseSensitiveNamesKey])
            .volumeSupportsCaseSensitiveNames ?? false
        guard !caseSensitive else { return }
        try FileManager.default.moveItem(at: t.root, to: t.base.appendingPathComponent("MOUNT"))
        #expect(throws: GrantedFileError.renamed(component: "mount")) { try t.access.write(relative: ["x.md"], content: "x") }
        #expect(throws: GrantedFileError.renamed(component: "mount")) { _ = try t.access.read(relative: ["x.md"]) }
        #expect(t.names(t.base.appendingPathComponent("MOUNT")) == ["sub"], "nothing was written")
    }

    @Test("a root under the system symlinks — /var/folders, /tmp — opens and writes, staging inside (N-H1)")
    func rootUnderTmpIsWalkable() throws {
        // Every root in this suite lives under NSTemporaryDirectory() (`/var/folders/…`, and `/var` is a
        // symlink to `/private/var`), so the suite itself proves the firmlink case; this test says so
        // out loud and adds the `/tmp` spelling the Verification demo uses.
        let t = try tree(); defer { t.tearDown() }
        #expect(t.root.path.hasPrefix("/var/") || t.root.path.hasPrefix("/private/var/"))
        #expect(IrisPaths.canonicalPath(t.root.path) == t.root.path, "the stored (canonical) spelling is what the walk is handed")
        try t.access.write(relative: ["sub", "tmp.md"], content: "ok")
        #expect(try t.access.read(relative: ["sub", "tmp.md"]) == "ok")
        #expect(t.names(t.root.appendingPathComponent("sub")) == ["tmp.md"])

        let tmp = URL(fileURLWithPath: "/tmp").appendingPathComponent("iris-gwalk-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: tmp, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: tmp) }
        let stored = IrisPaths.canonicalPath(tmp.path)
        #expect(stored.hasPrefix("/tmp/"), "canonicalPath strips /private (measured)")
        try GrantedFileAccess(root: stored).write(relative: ["hello.md"], content: "demo")
        #expect(try String(contentsOf: tmp.appendingPathComponent("hello.md"), encoding: .utf8) == "demo")

        // A root that no longer resolves is its own refusal, not a symlink sentence.
        try FileManager.default.removeItem(at: tmp)
        #expect(throws: GrantedFileError.rootUnavailable(stored)) { try GrantedFileAccess(root: stored).write(relative: ["x"], content: "x") }
    }

    @Test("read_file walks the same way: content back, a missing file named, no descent through a link")
    func readThroughTheWalk() throws {
        let t = try tree(); defer { t.tearDown() }
        try "hello".write(to: t.root.appendingPathComponent("sub/r.md"), atomically: true, encoding: .utf8)
        #expect(try t.access.read(relative: ["sub", "r.md"]) == "hello")
        #expect(throws: GrantedFileError.missing(component: "gone.md")) { _ = try t.access.read(relative: ["sub", "gone.md"]) }
        #expect(throws: GrantedFileError.missing(component: "nodir")) { _ = try t.access.read(relative: ["nodir", "r.md"]) }
        #expect(throws: GrantedFileError.notADirectory(component: "r.md")) { _ = try t.access.read(relative: ["sub", "r.md", "deeper"]) }
        // #337: no components is the root itself, which reads as its listing.
        #expect(try t.access.read(relative: []).contains("\nsub/\n"))
    }

    @Test("read lists a directory (#337) and refuses a FIFO with its own sentence, and the FIFO answer comes back promptly")
    func readRefusesNonRegularFiles() async throws {
        let t = try tree(); defer { t.tearDown() }
        #expect(try t.access.read(relative: ["sub"]).hasSuffix("(empty)"))
        // Measured by review: a plain `open(O_RDONLY)` of a FIFO blocks until a writer appears, which
        // would park a job's run on the watchdog. The walk opens `O_NONBLOCK`, asks `fstat`, and refuses.
        let fifo = t.root.appendingPathComponent("sub/pipe")
        #expect(mkfifo(fifo.path, 0o644) == 0)
        enum Outcome: Equatable { case threw(GrantedFileError), readBack, timedOut }
        let access = t.access
        let (outcomes, sink) = AsyncStream<Outcome>.makeStream()
        let reader = Task.detached {
            do { _ = try access.read(relative: ["sub", "pipe"]); sink.yield(.readBack) }
            catch let error as GrantedFileError { sink.yield(.threw(error)) }
            catch { sink.yield(.readBack) }
        }
        let timer = Task.detached { try? await Task.sleep(for: .seconds(5)); sink.yield(.timedOut) }
        var first: Outcome = .timedOut
        for await outcome in outcomes { first = outcome; break }
        // The loser is cancelled once the winner has arrived, so a passing run does not leave a
        // five-second sleeper behind it (and a failing one does not leave a parked reader).
        reader.cancel(); timer.cancel()
        #expect(first == .threw(.notARegularFile(component: "pipe")))
    }

    @Test("a root spelled with one trailing slash is walked as its canonical spelling, as relativeComponents reads it")
    func trailingSlashRootIsWalked() throws {
        let t = try tree(); defer { t.tearDown() }
        try GrantedFileAccess(root: t.root.path + "/").write(relative: ["slash.md"], content: "ok")
        #expect(try String(contentsOf: t.root.appendingPathComponent("slash.md"), encoding: .utf8) == "ok")
        #expect(try GrantedFileAccess(root: t.root.path + "/").read(relative: ["slash.md"]) == "ok")
    }

    @Test("a post-hook path that lands in a nested entry under the decided mount is refused: the decision is walked, never a substitute")
    func nestedEntryUnderDecidedMountIsRefused() async throws {
        let t = try tree(); defer { t.tearDown() }
        // `mount/` read-write with `mount/sub` read-only nested inside it. The dispatcher decided
        // `mount/x.md` → the outer entry; a BeforeTool hook then rewrote the path to `mount/sub/y.md`,
        // which is spelled under the decided mount but covered by the inner, read-only one — where a
        // command would get EROFS. Containment alone would let the host write land.
        let outer = ContainerMount(source: t.root.path)
        let inner = ContainerMount(source: t.root.appendingPathComponent("sub").path, readOnly: true)
        let grant = JobGrant(mounts: [outer, inner])
        let executor = ToolExecutor()
        let rewritten = t.root.appendingPathComponent("sub/y.md").path
        #expect(await executor.execute(name: "write_file", args: ["path": .string(rewritten), "content": .string("x")],
                                       cwd: t.root.path, grant: grant, grantedMount: outer)
                == ToolExecutor.notUnderGrantedDirectory(t.root.path))
        #expect(!FileManager.default.fileExists(atPath: rewritten))
        // The same path decided on its own entry reads; a path decided on the outer entry and still
        // covered by it writes. The check is equality with the decision, not a fresh decision.
        try "in".write(to: URL(fileURLWithPath: rewritten), atomically: true, encoding: .utf8)
        #expect(await executor.execute(name: "read_file", args: ["path": .string(rewritten)], cwd: t.root.path,
                                       grant: grant, grantedMount: inner) == "in")
        let plain = t.root.appendingPathComponent("top.md").path
        #expect(await executor.execute(name: "write_file", args: ["path": .string(plain), "content": .string("ok")],
                                       cwd: t.root.path, grant: grant, grantedMount: outer) == "Successfully wrote to \(plain)")
    }

    @Test("the executor's granted pair return the tool's sentences, and execute(grantedMount:) routes to them")
    func executorRoutesToTheWalk() async throws {
        let t = try tree(); defer { t.tearDown() }
        let executor = ToolExecutor()
        let mount = ContainerMount(source: t.root.path)
        let grant = JobGrant(mounts: [mount])
        let target = t.root.appendingPathComponent("sub/e.md").path
        let wrote = await executor.execute(name: "write_file", args: ["path": .string(target), "content": .string("via walk")],
                                           cwd: t.root.path, grant: grant, grantedMount: mount)
        #expect(wrote == "Successfully wrote to \(target)", "the sentence writtenPaths reads, so the self-write filter is fed as before")
        #expect(try String(contentsOf: URL(fileURLWithPath: target), encoding: .utf8) == "via walk")
        #expect(await executor.execute(name: "read_file", args: ["path": .string("sub/e.md")], cwd: t.root.path,
                                       grant: grant, grantedMount: mount) == "via walk")

        // A path a hook rewrote out from under the decided mount is refused, never re-routed to Foundation.
        // (`execute` receives the hook layer's `execArgs` — iris.swift:3249 — so this IS the post-hook path;
        // `HookManager.shared` is process-global and is not driven from a test, invariant 7.)
        let elsewhere = t.outside.appendingPathComponent("h.md").path
        #expect(await executor.execute(name: "write_file", args: ["path": .string(elsewhere), "content": .string("x")],
                                       cwd: t.root.path, grant: grant, grantedMount: mount)
                == ToolExecutor.notUnderGrantedDirectory(t.root.path))
        // …including one that is spelled under the mount and climbs out with `..` (H2).
        #expect(await executor.execute(name: "write_file", args: ["path": .string(t.root.path + "/../outside/h.md"), "content": .string("x")],
                                       cwd: t.root.path, grant: grant, grantedMount: mount)
                == ToolExecutor.notUnderGrantedDirectory(t.root.path))
        #expect(t.names(t.outside).isEmpty)

        // A granted conversation whose decision was nil: refused, never Foundation (H1 — the invariant).
        let inside = t.root.appendingPathComponent("sub/undecided.md").path
        #expect(await executor.execute(name: "write_file", args: ["path": .string(inside), "content": .string("x")],
                                       cwd: t.root.path, grant: grant, grantedMount: nil)
                == ToolExecutor.notDecidedInsideGrant("write_file"))
        #expect(await executor.execute(name: "read_file", args: ["path": .string(inside)], cwd: t.root.path, grant: grant, grantedMount: nil)
                == ToolExecutor.notDecidedInsideGrant("read_file"))
        #expect(!FileManager.default.fileExists(atPath: inside))

        // Through a link that leaves the mount: its real path is no longer covered by the decided
        // entry, so the executor's own re-check refuses it before the walk (Minor 5).
        try FileManager.default.createSymbolicLink(at: t.root.appendingPathComponent("link"), withDestinationURL: t.outside)
        #expect(await executor.execute(name: "write_file", args: ["path": .string("link/x.md"), "content": .string("x")],
                                       cwd: t.root.path, grant: grant, grantedMount: mount)
                == ToolExecutor.notUnderGrantedDirectory(t.root.path))
        #expect(t.names(t.outside).isEmpty)
        // Through a link that stays inside the mount: covered, so it reaches the walk, whose sentence names the link.
        try FileManager.default.createSymbolicLink(at: t.root.appendingPathComponent("inlink"), withDestinationURL: t.root.appendingPathComponent("sub"))
        let viaLink = await executor.execute(name: "write_file", args: ["path": .string("inlink/x.md"), "content": .string("x")],
                                             cwd: t.root.path, grant: grant, grantedMount: mount)
        #expect(viaLink == "Error writing file: \(GrantedFileError.symlink(component: "inlink").message)")
        #expect(!FileManager.default.fileExists(atPath: t.root.appendingPathComponent("sub/x.md").path))

        // No decided mount: today's Foundation path, unchanged (an attended call, or an approved/allowlisted one).
        let plain = await executor.execute(name: "write_file", args: ["path": .string(elsewhere), "content": .string("plain")], cwd: nil)
        #expect(plain == "Successfully wrote to \(elsewhere)")
    }
}

import XCTest
import PDFKit
import AppKit
@testable import IrisKit

final class AttachmentProcessorTests: XCTestCase {
    var tempDirectory: URL!

    override func setUpWithError() throws {
        try super.setUpWithError()
        tempDirectory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDirectory, withIntermediateDirectories: true)
    }

    override func tearDownWithError() throws {
        try? FileManager.default.removeItem(at: tempDirectory)
        try super.tearDownWithError()
    }

    // MARK: - Categorization Tests

    func testCategorization() {
        let testCases: [(String, AttachmentCategory, String)] = [
            ("image.png", .image, "image/png"),
            ("photo.jpg", .image, "image/jpeg"),
            ("photo.jpeg", .image, "image/jpeg"),
            ("animation.gif", .image, "image/gif"),
            ("graphic.webp", .image, "image/webp"),
            ("document.pdf", .pdf, "application/pdf"),
            ("word.docx", .document, "application/vnd.openxmlformats-officedocument.wordprocessingml.document"),
            ("notes.rtf", .document, "application/rtf"),
            ("plain.txt", .text, "text/plain"),
            ("readme.md", .text, "text/plain"),
            ("config.json", .text, "text/plain"),
            ("script.swift", .text, "text/plain"),
            ("binary.exe", .unknown, "application/octet-stream")
        ]

        for (filename, expectedCategory, expectedMime) in testCases {
            let url = URL(fileURLWithPath: filename)
            let (category, mimeType) = AttachmentProcessor.categorize(url: url)
            XCTAssertEqual(category, expectedCategory, "Failed category for \(filename)")
            XCTAssertEqual(mimeType, expectedMime, "Failed mimeType for \(filename)")
        }
    }

    // MARK: - Text Extraction Tests

    func testTextFileExtraction() async throws {
        let fileURL = tempDirectory.appendingPathComponent("sample.txt")
        let content = "Hello World File Attachment\nSecond Line of Content"
        try content.write(to: fileURL, atomically: true, encoding: .utf8)

        let attachment = FileAttachment(
            filename: fileURL.lastPathComponent,
            fileURL: fileURL,
            mimeType: "text/plain",
            fileSize: Int64(content.utf8.count),
            category: .text
        )

        let result = try await AttachmentProcessor.process(attachments: [attachment], primarySupportsVision: true)
        XCTAssertTrue(result.extractedPromptText.contains("<attached_file name=\"sample.txt\" mime=\"text/plain\">"))
        XCTAssertTrue(result.extractedPromptText.contains("Hello World File Attachment"))
        XCTAssertTrue(result.extractedPromptText.contains("Second Line of Content"))
        XCTAssertTrue(result.extractedPromptText.contains("</attached_file>"))
        XCTAssertTrue(result.warnings.isEmpty)
    }

    // MARK: - File Truncation Tests

    func testFileTruncation() async throws {
        let fileURL = tempDirectory.appendingPathComponent("long.txt")
        // Create text exceeding 100,000 characters
        let largeContent = String(repeating: "ABCDE12345", count: 11_000) // 110,000 chars
        try largeContent.write(to: fileURL, atomically: true, encoding: .utf8)

        let attachment = FileAttachment(
            filename: "long.txt",
            fileURL: fileURL,
            mimeType: "text/plain",
            fileSize: Int64(largeContent.utf8.count),
            category: .text
        )

        let result = try await AttachmentProcessor.process(attachments: [attachment], primarySupportsVision: true)
        XCTAssertTrue(result.extractedPromptText.contains("[Content truncated at 100,000 characters]"))
        // Check that actual content snippet length inside tag is truncated properly
        let prefixSnippet = String(largeContent.prefix(100_000))
        XCTAssertTrue(result.extractedPromptText.contains(prefixSnippet))
        let overflowSnippet = String(largeContent.prefix(100_005))
        XCTAssertFalse(result.extractedPromptText.contains(overflowSnippet))
    }

    // MARK: - PDF Extraction Tests

    func testPDFTextExtraction() async throws {
        let fileURL = tempDirectory.appendingPathComponent("sample.pdf")
        let pdfData = NSMutableData()

        let pdfMetaData = [
            kCGPDFContextCreator: "AttachmentProcessorTests",
            kCGPDFContextAuthor: "Iris"
        ]

        var mediaBox = CGRect(x: 0, y: 0, width: 612, height: 792)
        guard let consumer = CGDataConsumer(data: pdfData as CFMutableData),
              let context = CGContext(consumer: consumer, mediaBox: &mediaBox, pdfMetaData as CFDictionary) else {
            XCTFail("Failed to create PDF graphics context")
            return
        }

        context.beginPDFPage(nil)
        let sampleText = "PDF Text Extraction Sample Page Content"
        let font = NSFont.systemFont(ofSize: 12)
        let attrString = NSAttributedString(string: sampleText, attributes: [.font: font])
        let framesetter = CTFramesetterCreateWithAttributedString(attrString as CFAttributedString)
        let frameRect = CGRect(x: 50, y: 50, width: 500, height: 700)
        let path = CGPath(rect: frameRect, transform: nil)
        let frame = CTFramesetterCreateFrame(framesetter, CFRangeMake(0, attrString.length), path, nil)
        CTFrameDraw(frame, context)
        context.endPDFPage()
        context.closePDF()

        try pdfData.write(to: fileURL, options: .atomic)

        let attachment = FileAttachment(
            filename: "sample.pdf",
            fileURL: fileURL,
            mimeType: "application/pdf",
            fileSize: Int64(pdfData.length),
            category: .pdf
        )

        let result = try await AttachmentProcessor.process(attachments: [attachment], primarySupportsVision: true)
        XCTAssertTrue(result.extractedPromptText.contains("<attached_file name=\"sample.pdf\" mime=\"application/pdf\">"))
        XCTAssertTrue(result.extractedPromptText.contains("PDF Text Extraction Sample Page Content"))
        XCTAssertTrue(result.warnings.isEmpty)
    }

    // MARK: - RTF / Document Extraction Tests

    func testRTFDocumentExtraction() async throws {
        let fileURL = tempDirectory.appendingPathComponent("sample.rtf")
        let attributedString = NSAttributedString(string: "Rich Text Document Sample Content")
        let rtfData = try attributedString.data(from: NSRange(location: 0, length: attributedString.length), documentAttributes: [.documentType: NSAttributedString.DocumentType.rtf])
        try rtfData.write(to: fileURL)

        let attachment = FileAttachment(
            filename: "sample.rtf",
            fileURL: fileURL,
            mimeType: "application/rtf",
            fileSize: Int64(rtfData.count),
            category: .document
        )

        let result = try await AttachmentProcessor.process(attachments: [attachment], primarySupportsVision: true)
        XCTAssertTrue(result.extractedPromptText.contains("<attached_file name=\"sample.rtf\" mime=\"application/rtf\">"))
        XCTAssertTrue(result.extractedPromptText.contains("Rich Text Document Sample Content"))
        XCTAssertTrue(result.warnings.isEmpty)
    }

    // MARK: - Image Inline Part Creation Tests

    func testImageInlinePartCreationWithVisionSupport() async throws {
        let fileURL = tempDirectory.appendingPathComponent("test_image.png")
        let imageData = Data([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]) // Dummy PNG magic header bytes
        try imageData.write(to: fileURL)

        let attachment = FileAttachment(
            filename: "test_image.png",
            fileURL: fileURL,
            mimeType: "image/png",
            fileSize: Int64(imageData.count),
            category: .image
        )

        let result = try await AttachmentProcessor.process(attachments: [attachment], primarySupportsVision: true)
        XCTAssertEqual(result.inlineParts.count, 1)
        XCTAssertEqual(result.inlineParts[0].inlineData?.mimeType, "image/png")
        XCTAssertEqual(result.inlineParts[0].inlineData?.data, imageData.base64EncodedString())
        XCTAssertTrue(result.extractedPromptText.isEmpty)
        XCTAssertTrue(result.warnings.isEmpty)
    }

    func testImageIgnoredWhenVisionNotSupported() async throws {
        let fileURL = tempDirectory.appendingPathComponent("test_image.png")
        let imageData = Data([0x89, 0x50, 0x4E, 0x47])
        try imageData.write(to: fileURL)

        let attachment = FileAttachment(
            filename: "test_image.png",
            fileURL: fileURL,
            mimeType: "image/png",
            fileSize: Int64(imageData.count),
            category: .image
        )

        let result = try await AttachmentProcessor.process(attachments: [attachment], primarySupportsVision: false)
        XCTAssertTrue(result.inlineParts.isEmpty)
        XCTAssertTrue(result.extractedPromptText.isEmpty)
        XCTAssertTrue(result.warnings.isEmpty)
    }

    // MARK: - Error Handling & Warnings Tests

    func testFileNotFoundWarning() async throws {
        let fileURL = tempDirectory.appendingPathComponent("nonexistent.txt")
        let attachment = FileAttachment(
            filename: "nonexistent.txt",
            fileURL: fileURL,
            mimeType: "text/plain",
            fileSize: 100,
            category: .text
        )

        let result = try await AttachmentProcessor.process(attachments: [attachment], primarySupportsVision: true)
        XCTAssertEqual(result.warnings.count, 1)
        XCTAssertTrue(result.warnings[0].contains("File not found: nonexistent.txt"))
        XCTAssertTrue(result.extractedPromptText.isEmpty)
    }

    func testImageFileSizeLimitExceeded() async throws {
        let fileURL = tempDirectory.appendingPathComponent("oversized.png")
        try "dummy".write(to: fileURL, atomically: true, encoding: .utf8)
        let attachment = FileAttachment(
            filename: "oversized.png",
            fileURL: fileURL,
            mimeType: "image/png",
            fileSize: 20_000_001,
            category: .image
        )

        let result = try await AttachmentProcessor.process(attachments: [attachment], primarySupportsVision: true)
        XCTAssertEqual(result.warnings.count, 1)
        XCTAssertEqual(result.warnings[0], "File 'oversized.png' exceeds the maximum allowed size limit.")
        XCTAssertTrue(result.inlineParts.isEmpty)
    }

    func testDocumentFileSizeLimitExceeded() async throws {
        let fileURL = tempDirectory.appendingPathComponent("oversized.txt")
        try "dummy".write(to: fileURL, atomically: true, encoding: .utf8)
        let attachment = FileAttachment(
            filename: "oversized.txt",
            fileURL: fileURL,
            mimeType: "text/plain",
            fileSize: 50_000_001,
            category: .text
        )

        let result = try await AttachmentProcessor.process(attachments: [attachment], primarySupportsVision: true)
        XCTAssertEqual(result.warnings.count, 1)
        XCTAssertEqual(result.warnings[0], "File 'oversized.txt' exceeds the maximum allowed size limit.")
        XCTAssertTrue(result.extractedPromptText.isEmpty)
    }
}

import Testing
import Foundation
@testable import IrisKit

/// #521: a blocked run's card waited on Vibecop's verdict before it was saved, and a local engine's
/// verdict can take seconds. A CLI exit-now in that wait left a `blockedOnApproval` row, with its
/// call stored, and no card ever offering the approval. The card is saved first and the verdict
/// written onto it afterwards, unless the run was approved or dismissed meanwhile.
@MainActor
@Suite("A blocked run's card is saved before Vibecop's verdict (#521)", .timeLimit(.minutes(1)))
struct BlockedCardBeforeVerdictTests {

    private func isolatedConfig() -> (ConfigManager, () -> Void) {
        let name = "iris-blockedcard-\(UUID().uuidString)"
        let store = UserDefaults(suiteName: name)!
        let config = ConfigManager(store: store)
        config.enableVibecop = true
        return (config, {
            store.removePersistentDomain(forName: name)
            IrisDefaults.removeSuiteFile(named: name, in: IrisDefaults.preferencesDirectory)
        })
    }

    /// A run whose one tool call is refused for want of approval, then a closing reply.
    private func harness() throws -> (ConversationStore, AppState, IrisEngine, Job) {
        let command = "true --never-run-\(UUID().uuidString)"
        let store = try ConversationStore.inMemory()
        let state = AppState(store: store, tier2Provisioning: .provisioned, tier3Provisioning: .provisioned)
        state.conversations.removeAll()
        let engine = IrisEngine(state: state, tier: .medium, client: FakeLLMClient(responses: [
            GeminiResponse(candidates: [Candidate(content: Content(role: "model", parts: [
                Part(functionCall: FunctionCall(name: "run_command", args: ["command": .string(command)]))]))],
                           usageMetadata: nil),
            GeminiResponse(candidates: [Candidate(content: Content(role: "model", parts: [
                Part(text: "blocked.")]))], usageMetadata: nil),
        ]), protectionEnabled: false, sessionPeerCount: 0)
        let job = Job(name: "needs-hands", prompt: "Do the thing.",
                      trigger: .schedule(.interval(seconds: 60)), profile: .mutating)
        try store.ledger.upsert(job)
        return (store, state, engine, job)
    }

    /// Answers DENY, but only once released: a local model mid-inference.
    private final class HeldVibecop: AuxiliaryInferenceEngine, @unchecked Sendable {
        private let lock = NSLock()
        private var entered = 0
        private var open = false
        var calls: Int { lock.withLock { entered } }
        func release() { lock.withLock { open = true } }
        func loadModel(config: AuxiliaryModelConfig) async throws {}
        func unloadModel() async {}
        func generate(prompt: String, jsonSchema: String?) async throws -> String {
            lock.withLock { entered += 1 }
            let deadline = TestClock.deadline(20)
            while !lock.withLock({ open }), TestClock.now() < deadline {
                try await Task.sleep(nanoseconds: 10_000_000)
            }
            return #"{"decision":"DENY","reason":"this deletes things"}"#
        }
    }

    private func until(within seconds: TimeInterval = 20, _ condition: () -> Bool) async -> Bool {
        let deadline = TestClock.deadline(seconds)
        while !condition() {
            if TestClock.now() >= deadline { return false }
            try? await Task.sleep(nanoseconds: 10_000_000)
        }
        return true
    }

    private func persistedCards(_ store: ConversationStore) throws -> [EventCard] {
        try store.loadAll().conversations.flatMap(\.messages).filter { $0.role == .event }
            .compactMap { EventCard.decode($0.content) }
    }

    private func cards(_ state: AppState) -> [EventCard] {
        state.conversations.flatMap(\.messages).filter { $0.role == .event }
            .compactMap { EventCard.decode($0.content) }
    }

    @Test("a CLI run's blocked card is in the store while the verdict is still being taken")
    func cardSavedBeforeVerdict() async throws {
        let (store, state, engine, job) = try harness()
        let (config, teardown) = isolatedConfig()
        defer { teardown() }
        let stop = RunStop(grace: 5, terminateGroups: {})
        let runner = JobRunner(state: state, engine: engine, ledger: store.ledger, endSandboxSession: { _ in },
                               config: config, activity: RecordingActivity(), sandboxAvailable: { true }, stop: stop)
        let vibecop = HeldVibecop()
        defer { vibecop.release() }

        let fire = AuxiliaryModelManager.$scopedEngines.withValue(["vibecop": vibecop]) {
            Task { await runner.fire(job: job, origin: .manual) }
        }
        try #require(await until { vibecop.calls >= 1 }, "the verdict is being taken")
        // The Ctrl-C that would come before an exit-now. The run has already ended, so it stops nothing.
        _ = stop.request(reason: RunStop.reason(for: SIGINT))

        // What an exit-now here would leave on disk.
        let run = try #require(try store.ledger.runs(jobId: job.id, limit: 1).first)
        #expect(run.status == .blockedOnApproval)
        #expect(run.blockedCall != nil)
        let saved = try persistedCards(store).filter { $0.runId == run.id }
        #expect(saved.count == 1, "the blocked row already has its card in the store")
        #expect(saved.first?.offersApproval == true)
        #expect(saved.first?.vibecopVerdict == nil, "the verdict is not in yet")

        vibecop.release()
        _ = try await value(of: fire)
        let final = try persistedCards(store).filter { $0.runId == run.id }
        #expect(final.count == 1, "the verdict rewrote the card rather than adding a second one")
        #expect(final.first?.vibecopVerdict == "DENY")
        #expect(final.first?.vibecopReason == "this deletes things")
    }

    @Test("an app run's blocked card is delivered before the verdict, and gets it afterwards")
    func appCardGetsTheVerdictLater() async throws {
        let (store, state, engine, job) = try harness()
        let (config, teardown) = isolatedConfig()
        defer { teardown() }
        let runner = JobRunner(state: state, engine: engine, ledger: store.ledger, endSandboxSession: { _ in },
                               config: config, activity: RecordingActivity(), sandboxAvailable: { true })
        let vibecop = HeldVibecop()
        defer { vibecop.release() }

        let fire = AuxiliaryModelManager.$scopedEngines.withValue(["vibecop": vibecop]) {
            Task { await runner.fire(job: job, origin: .schedule) }
        }
        try #require(await until { vibecop.calls >= 1 }, "the verdict is being taken")
        #expect(cards(state).count == 1, "the card is already in the transcript")
        #expect(cards(state).first?.vibecopVerdict == nil)

        vibecop.release()
        _ = try await value(of: fire)
        #expect(cards(state).count == 1)
        #expect(cards(state).first?.vibecopVerdict == "DENY")
    }

    @Test("a verdict that lands after the run was approved does not rewrite its card")
    func approvedDuringVerdictKeepsTheCard() async throws {
        let (store, state, engine, job) = try harness()
        let (config, teardown) = isolatedConfig()
        defer { teardown() }
        let runner = JobRunner(state: state, engine: engine, ledger: store.ledger, endSandboxSession: { _ in },
                               config: config, activity: RecordingActivity(), sandboxAvailable: { true })
        let vibecop = HeldVibecop()
        defer { vibecop.release() }

        let fire = AuxiliaryModelManager.$scopedEngines.withValue(["vibecop": vibecop]) {
            Task { await runner.fire(job: job, origin: .schedule) }
        }
        try #require(await until { vibecop.calls >= 1 }, "the verdict is being taken")
        let run = try #require(try store.ledger.runs(jobId: job.id, limit: 1).first)
        let before = try #require(state.conversations.flatMap(\.messages).first { $0.role == .event })
        // What "Approve and run" writes first: the one-shot claim, which also acknowledges the run.
        #expect(try store.ledger.markApproved(runId: run.id, at: Date()) == true)

        vibecop.release()
        _ = try await value(of: fire)
        let after = try #require(state.conversations.flatMap(\.messages).first { $0.id == before.id })
        #expect(after.content == before.content, "the card the person acted on is left as it was")
        #expect(cards(state).count == 1)
    }

    /// A click's ledger write is the runner's or a detached task's and can come after the verdict
    /// (review of #526). The click itself is recorded on the main actor as it lands. Here the
    /// click's runner is another store's, so its ledger write never reaches this one: only that
    /// record can stop the rewrite.
    @Test("a verdict that lands after the Approve click, before its ledger write, does not rewrite the card")
    func approveClickBeforeItsWriteKeepsTheCard() async throws {
        let (store, state, engine, job) = try harness()
        let (config, teardown) = isolatedConfig()
        defer { teardown() }
        let runner = JobRunner(state: state, engine: engine, ledger: store.ledger, endSandboxSession: { _ in },
                               config: config, activity: RecordingActivity(), sandboxAvailable: { true })
        let elsewhere = AppState(store: try ConversationStore.inMemory(), tier2Provisioning: .provisioned,
                                 tier3Provisioning: .provisioned)
        let vibecop = HeldVibecop()
        defer { vibecop.release() }

        let fire = AuxiliaryModelManager.$scopedEngines.withValue(["vibecop": vibecop]) {
            Task { await runner.fire(job: job, origin: .schedule) }
        }
        try #require(await until { vibecop.calls >= 1 }, "the verdict is being taken")
        let run = try #require(try store.ledger.runs(jobId: job.id, limit: 1).first)
        let before = try #require(state.conversations.flatMap(\.messages).first { $0.role == .event })
        state.installEngine(IrisEngine(state: elsewhere, client: FakeLLMClient(responses: []), protectionEnabled: false))
        state.approveBlockedCall(runId: run.id)
        #expect(state.runsActedOn.contains(run.id), "recorded at the click, before any hop")

        vibecop.release()
        _ = try await value(of: fire)
        #expect(try store.ledger.run(id: run.id)?.acknowledgedAt == nil, "no ledger write reached this store")
        let after = try #require(state.conversations.flatMap(\.messages).first { $0.id == before.id })
        #expect(after.content == before.content, "the card the person clicked is left as it was")
        withExtendedLifetime(elsewhere) {}
    }

    @Test("Dismiss and Acknowledge record the run at the click, before their ledger write")
    func dismissRecordsAtTheClick() throws {
        let state = AppState(store: try ConversationStore.inMemory(), tier2Provisioning: .provisioned,
                             tier3Provisioning: .provisioned)
        let id = UUID()
        _ = state.dismissEventCard(runId: id)
